"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { api, ApiError } from "./api";
import { SlotPicker, type PickedSlot } from "./SlotPicker";
import { Button, Field, inputClass, Notice } from "./ui";

type Props = {
  token: string; canChange: boolean; whyNot: string; live: boolean; partySize: number; maxParty: number;
  date: string; today: string; maxDate: string; bookAgainHref: string;
  calendar: { title: string; start: string; end: string; location: string; reference: string };
};

const icsDate = (iso: string) => iso.replace(/[-:]/g, "").replace(/\.\d{3}/, "");
const icsText = (s: string) => s.replace(/[\;,]/g, (c) => `\\${c}`).replace(/\n/g, "\\n");

export function TicketActions(p: Props) {
  const router = useRouter();
  const [mode, setMode] = useState<"idle" | "reschedule" | "cancel">("idle");
  const [date, setDate] = useState(p.date < p.today ? p.today : p.date);
  const [party, setParty] = useState(p.partySize);
  const [slot, setSlot] = useState<PickedSlot | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [done, setDone] = useState("");

  function downloadCalendar() {
    const ics = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//AI Book & Check In//EN", "BEGIN:VEVENT", `UID:${p.calendar.reference}-${icsDate(p.calendar.start)}@ai-book-checkin`,
      `DTSTAMP:${icsDate(new Date().toISOString())}`, `DTSTART:${icsDate(p.calendar.start)}`, `DTEND:${icsDate(p.calendar.end)}`,
      `SUMMARY:${icsText(p.calendar.title)}`, `LOCATION:${icsText(p.calendar.location)}`, `DESCRIPTION:${icsText(`Reference ${p.calendar.reference}\n${window.location.href}`)}`, "END:VEVENT", "END:VCALENDAR"].join("\r\n");
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([ics], { type: "text/calendar" }));
    a.download = `reservation-${p.calendar.reference}.ics`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  }

  async function run(fn: () => Promise<unknown>, message: string) {
    setBusy(true); setError("");
    try { await fn(); setDone(message); setMode("idle"); setSlot(null); router.refresh(); }
    catch (e) { setError((e as ApiError).message); }
    finally { setBusy(false); }
  }

  return (
    <div className="no-print mt-5 space-y-3">
      {done && <Notice tone="ok">{done}</Notice>}
      {p.live && mode === "idle" && (
        <>
          <div className="grid grid-cols-2 gap-3">
            <Button variant="quiet" onClick={() => window.print()}>Print or save as PDF</Button>
            <Button variant="quiet" onClick={downloadCalendar}>Add to calendar</Button>
          </div>
          {p.canChange ? (
            <div className="grid grid-cols-2 gap-3">
              <Button variant="quiet" onClick={() => { setMode("reschedule"); setDone(""); }}>Change date or time</Button>
              <Button variant="danger" onClick={() => { setMode("cancel"); setDone(""); }}>Cancel reservation</Button>
            </div>
          ) : <p className="text-center text-[15px] text-ink-soft">{p.whyNot}</p>}
        </>
      )}
      {!p.live && <a href={p.bookAgainHref} className="flex min-h-11 items-center justify-center rounded-xl bg-brand font-semibold text-white">Make a new reservation</a>}

      {mode === "cancel" && (
        <div className="space-y-3 rounded-2xl bg-white p-5 ring-1 ring-line">
          <p className="font-semibold">Cancel this reservation?</p>
          <p className="text-[15px] text-ink-soft">Your ticket will stop working straight away. This cannot be undone.</p>
          {error && <Notice tone="error">{error}</Notice>}
          <div className="flex gap-3">
            <Button variant="quiet" disabled={busy} onClick={() => { setMode("idle"); setError(""); }}>Keep it</Button>
            <Button variant="danger" disabled={busy} className="flex-1" onClick={() => run(() => api(`/api/t/${p.token}`, { method: "DELETE" }), "Your reservation is cancelled.")}>{busy ? "Cancelling…" : "Yes, cancel it"}</Button>
          </div>
        </div>
      )}

      {mode === "reschedule" && (
        <div className="space-y-4 rounded-2xl bg-white p-5 ring-1 ring-line">
          <p className="font-semibold">Choose a new date and time</p>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Date"><input type="date" className={inputClass} value={date} min={p.today} max={p.maxDate} onChange={(e) => { setDate(e.target.value); setSlot(null); }} /></Field>
            <Field label="People">
              <select className={inputClass} value={party} onChange={(e) => { setParty(Number(e.target.value)); setSlot(null); }}>
                {Array.from({ length: Math.max(p.maxParty, p.partySize) }, (_, i) => i + 1).map((n) => <option key={n}>{n}</option>)}
              </select>
            </Field>
          </div>
          <SlotPicker endpoint={`/api/t/${p.token}`} date={date} party={party} selected={slot?.start ?? null} onPick={setSlot} />
          {error && <Notice tone="error">{error}</Notice>}
          <div className="flex gap-3">
            <Button variant="quiet" disabled={busy} onClick={() => { setMode("idle"); setError(""); }}>Back</Button>
            <Button disabled={busy || !slot} className="flex-1" onClick={() => run(() => api(`/api/t/${p.token}`, { method: "PATCH", body: { startsAt: slot!.start, partySize: party } }), "Your reservation has been moved. Your ticket stays the same.")}>
              {busy ? "Saving…" : slot ? `Move to ${slot.time}` : "Choose a time"}
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}
